import pickle
import numpy as np
import sys

file_path = sys.argv[1]
print(f"Examining {file_path}...")

with open(file_path, 'rb') as f:
    data = pickle.load(f)

    print(f"Type: {type(data)}")

    if hasattr(data, 'shape'):
        print(f"Shape: {data.shape}")
    elif hasattr(data, '__len__'):
        print(f"Length: {len(data)}")
    else:
        print("No shape or length information")

    if hasattr(data, '__getitem__'):
        try:
            if isinstance(data, np.ndarray):
                print(f"Sample data: {data[:5]}")
                print(f"Unique classes: {np.unique(data) if data.size < 100 else 'Too many to display'}")
            else:
                print(f"First few items: {data[:5]}")
        except:
            print("Cannot slice the data")
